.ds{--p-bg:#ffffff;--p-surface:#f1f3f6;--p-high:#fafbfc;--p-hover:#e1e6ed;--p-row-active:#e5e9f2;--p-disabled:#dce1e8;--p-glass:#f6f8fbe8;--p-backdrop:#2c333d66;--p-tile:#f2f3f0;--p-tile-header:#f3f4f1;--p-image-well:#e7e9e4;--p-selected-surface:#e7f0eb;--p-ink:#2c333d;--p-muted:#59636f;--p-on-accent:#ffffff;--p-line:#c2cad5;--p-line-subtle:#cbd2dc;--p-control-border:#7b8592;--p-edge:#ffffff;--p-edge-soft:#ffffffa8;--p-accent:#303b48;--p-accent-hover:#25303d;--p-shade:#000;--p-highlight:#6153b5;--p-highlight-soft:#e2ddf3;--p-soft:#d3e8de;--p-mark:#ffbf63;--p-mark-hover:#ffd07b;--p-mark-alt:#9ad9aa;--p-error:#a3313e;--p-error-soft:#f9e8e9;--p-error-line:#d4a2a8;--p-success:#26614f;--p-success-soft:#e5f2eb;--p-success-line:#8fb8a5;--p-warning:#805719;--p-warning-soft:#f6efd9;--p-warning-line:#b9a16f;--p-font:Pretendard, sans-serif;--p-display-font:Outfit, Pretendard, sans-serif;--p-text-sm:13px;--p-text-md:16px;--p-text-lg:24px;--p-space-xs:8px;--p-space-sm:12px;--p-space-md:16px;--p-space-lg:24px;--p-space-xl:32px;--p-radius:24px;--p-control-radius:16px;--p-inner-radius:12px;--p-shadow:6px 7px 16px #bbc4d166, -5px -5px 14px #ffffffed;--p-raised:3px 4px 8px #b9c3d066, -3px -3px 8px #ffffffed;--p-inset:inset 3px 3px 6px #b7c1cf55, inset -3px -3px 6px #ffffffd9;--p-pressed:inset 3px 3px 6px #15222f60,inset -1px -1px 3px #ffffff18;--p-float:0 12px 32px #26394d26;--p-lift:0 3px 5px #24314526;--p-control-shadow:0 3px 5px #24314526,inset 0 1px 0 #ffffff24;--p-selected-shadow:0 2px 5px #24314526;--p-knob-shadow:0 1px 3px #26344726;--p-glass-shadow:0 8px 24px #38465e12;--p-dialog-shadow:0 24px 80px #26344740;--p-drop:0 10px 12px #24293616;--p-ring:inset 0 0 0 2px #24293610;--p-focus-glow:0 0 0 2px #ed667b33;}
.ds {
  color:var(--p-ink); background:var(--p-bg); font:var(--p-text-md)/1.5 var(--p-font);
  color-scheme:light; word-break:keep-all; overflow-wrap:anywhere; text-align:left;
}
.ds,.ds * { box-sizing:border-box; }
.ds [hidden] { display:none!important; }
.ds :is(h1,h2,h3,p,fieldset) { margin:0; }
.ds :is(button,input,select,textarea) { font:inherit; color:inherit; letter-spacing:inherit; }
.ds button { cursor:pointer; touch-action:manipulation; }
.ds button:disabled { cursor:not-allowed; }
.ds :is(button,input,select,textarea,a,[tabindex]):focus-visible { outline:3px solid var(--p-highlight); outline-offset:3px; }
.ds .ui-icon { display:inline-block; width:20px; height:20px; flex-shrink:0; vertical-align:middle; }
.ds .ds-demo-note { font-size:var(--p-text-sm); margin-top:var(--p-space-sm); min-height:20px; color:var(--p-muted); }
.ds .ds-surface { border:1px solid var(--p-line); border-radius:var(--p-radius); background:var(--p-surface); }
.ds .ds-surface[data-material="raised"] { box-shadow:var(--p-shadow); border-color:var(--p-edge); }
.ds .ds-surface[data-material="inset"] { box-shadow:var(--p-inset); background:var(--p-bg); }
.ds .ds-surface[data-material="glass"] { background:var(--p-high); box-shadow:var(--p-glass-shadow); }
@supports (backdrop-filter:blur(16px)) { .ds .ds-surface[data-material="glass"] { background:var(--p-glass); backdrop-filter:blur(16px); } }
@media(prefers-reduced-transparency:reduce) { .ds .ds-surface[data-material="glass"] { background:var(--p-high); backdrop-filter:none; } }
@media(prefers-reduced-motion:reduce) { .ds * { transition:none!important; animation:none!important; } }

.ds .ds-button { display:inline-flex; justify-content:center; align-items:center; gap:var(--p-space-xs); min-width:48px; min-height:48px; padding:10px 20px; border:1px solid var(--p-accent); border-radius:var(--p-control-radius); background:var(--p-accent); color:var(--p-on-accent); font-size:14px; font-weight:650; line-height:1.4; box-shadow:var(--p-control-shadow); text-decoration:none; transition:background var(--p-duration),box-shadow var(--p-duration); }
.ds .ds-button[data-variant="outline"] { border-color:var(--p-control-border); color:var(--p-ink); background:var(--p-surface); box-shadow:var(--p-raised); }
.ds .ds-button[data-variant="ghost"] { color:var(--p-ink); background:transparent; border-color:transparent; box-shadow:none; }
.ds .ds-button[data-size="sm"] { min-height:44px; min-width:44px; padding:8px 16px; font-size:13px; }
.ds .ds-button[data-size="lg"] { min-height:56px; min-width:56px; padding:14px 24px; font-size:16px; }
.ds .ds-button[data-icon-only] { padding:10px; }
.ds .ds-button:not(:disabled):is(:hover,[data-state="hover"]) { background:color-mix(in srgb,var(--p-accent) 84%,var(--p-shade)); }
.ds .ds-button[data-variant="outline"]:not(:disabled):is(:hover,[data-state="hover"]) { background:var(--p-high); }
.ds .ds-button[data-variant="ghost"]:not(:disabled):is(:hover,[data-state="hover"]) { background:var(--p-disabled); }
.ds .ds-button:not(:disabled):is(:active,[data-state="pressed"]) { box-shadow:var(--p-pressed); }
.ds .ds-button:not([data-variant="primary"]):not(:disabled):is(:active,[data-state="pressed"]) { background:var(--p-bg); box-shadow:var(--p-inset); }
.ds .ds-button[data-state="focus"] { outline:3px solid var(--p-highlight); outline-offset:3px; }
.ds .ds-button:disabled { opacity:1; box-shadow:none; background:var(--p-disabled); border-color:var(--p-line); color:var(--p-muted); }
.ds .ds-button[aria-busy="true"] { background:var(--p-accent); color:var(--p-on-accent); border-color:var(--p-accent); }
.ds .ds-spinner { width:16px; height:16px; flex-shrink:0; border:2px solid currentColor; border-right-color:transparent; border-radius:50%; animation:ds-spin .8s linear infinite; }
@keyframes ds-spin { to { transform:rotate(360deg); } }
@media(prefers-reduced-motion:reduce) { .ds .ds-spinner { border-style:dotted; } }
/* looks: primary colors change per look, pill/cta change shape for every variant; disabled keeps the base state */
.ds .ds-button[data-look="soft"][data-variant="primary"]:not(:disabled) { background:var(--p-soft); border-color:transparent; color:var(--p-ink); box-shadow:none; }
.ds .ds-button[data-look="soft"][data-variant="primary"]:not(:disabled):is(:hover,[data-state="hover"]) { background:color-mix(in oklab,var(--p-soft) 86%,var(--p-ink)); }
.ds .ds-button[data-look="soft"][data-variant="primary"]:not(:disabled):is(:active,[data-state="pressed"]) { box-shadow:var(--p-inset); }
.ds .ds-button[data-look="line"][data-variant="primary"]:not(:disabled) { background:transparent; border:2px solid var(--p-accent); padding:9px 19px; color:var(--p-ink); box-shadow:none; }
.ds .ds-button[data-look="line"][data-variant="primary"]:not(:disabled):is(:hover,[data-state="hover"]) { background:var(--p-surface); }
.ds .ds-button[data-look="line"][data-variant="primary"]:not(:disabled):is(:active,[data-state="pressed"]) { background:var(--p-surface); box-shadow:var(--p-inset); }
.ds .ds-button[data-look="text"][data-variant="primary"]:not(:disabled) { background:transparent; border-color:transparent; color:var(--p-ink); box-shadow:none; text-decoration:underline 2px; text-underline-offset:5px; }
.ds .ds-button[data-look="text"][data-variant="primary"]:not(:disabled):is(:hover,[data-state="hover"]) { background:var(--p-surface); }
.ds .ds-button[data-look="text"][data-variant="primary"]:not(:disabled):is(:active,[data-state="pressed"]) { background:var(--p-surface); box-shadow:none; text-underline-offset:3px; }
.ds .ds-button:is([data-look="pill"],[data-look="cta"]) { border-radius:99px; }
.ds .ds-button[data-look="pill"]:not([data-icon-only]) { padding-inline:28px; }
.ds .ds-button[data-look="gradient"][data-variant="primary"]:not(:disabled) { background:linear-gradient(135deg,var(--p-accent),color-mix(in oklab,var(--p-accent) 45%,var(--p-success))); border-color:transparent; box-shadow:0 6px 16px color-mix(in oklab,var(--p-accent) 32%,transparent); }
.ds .ds-button[data-look="gradient"][data-variant="primary"]:not(:disabled):is(:hover,[data-state="hover"]) { background:linear-gradient(135deg,color-mix(in oklab,var(--p-accent) 80%,var(--p-ink)),color-mix(in oklab,var(--p-accent) 30%,var(--p-success))); }
.ds .ds-button[data-look="gradient"][data-variant="primary"]:not(:disabled):is(:active,[data-state="pressed"]) { box-shadow:inset 0 3px 6px color-mix(in oklab,var(--p-ink) 45%,transparent); }
.ds .ds-button[data-look="3d"][data-variant="primary"]:not(:disabled) { background:var(--p-high); border:2px solid var(--p-accent); padding:9px 19px; color:var(--p-ink); box-shadow:0 5px 0 var(--p-accent); transition:transform var(--p-duration),box-shadow var(--p-duration),background var(--p-duration); }
.ds .ds-button[data-look="3d"][data-variant="primary"]:not(:disabled):is(:hover,[data-state="hover"]) { background:var(--p-soft); }
.ds .ds-button[data-look="3d"][data-variant="primary"]:not(:disabled):is(:active,[data-state="pressed"]) { transform:translateY(5px); box-shadow:0 0 0 var(--p-accent); }
.ds .ds-button[data-look="neumorph"][data-variant="primary"]:not(:disabled) { background:var(--p-surface); border-color:transparent; border-radius:var(--p-radius); color:var(--p-ink); box-shadow:var(--p-shadow); }
.ds .ds-button[data-look="neumorph"][data-variant="primary"]:not(:disabled):is(:hover,[data-state="hover"]) { background:var(--p-high); }
.ds .ds-button[data-look="neumorph"][data-variant="primary"]:not(:disabled):is(:active,[data-state="pressed"]) { background:var(--p-surface); box-shadow:var(--p-inset); }
.ds .ds-button[data-look="glass"][data-variant="primary"]:not(:disabled) { background:linear-gradient(160deg,color-mix(in oklab,var(--p-high) 80%,transparent),color-mix(in oklab,var(--p-soft) 60%,transparent)); border-color:var(--p-line); color:var(--p-ink); box-shadow:inset 0 1px 0 var(--p-on-accent),0 8px 22px color-mix(in oklab,var(--p-ink) 14%,transparent); backdrop-filter:blur(12px); }
.ds .ds-button[data-look="glass"][data-variant="primary"]:not(:disabled):is(:hover,[data-state="hover"]) { background:linear-gradient(160deg,var(--p-high),color-mix(in oklab,var(--p-soft) 80%,transparent)); }
.ds .ds-button[data-look="glass"][data-variant="primary"]:not(:disabled):is(:active,[data-state="pressed"]) { box-shadow:var(--p-inset); }
@media(prefers-reduced-transparency:reduce) { .ds .ds-button[data-look="glass"][data-variant="primary"]:not(:disabled) { background:var(--p-high); backdrop-filter:none; } }
.ds .ds-button[data-look="cta"]:not([data-icon-only]) { gap:var(--p-space-sm); padding:6px 6px 6px 22px; }
.ds .ds-button[data-look="cta"]:not([data-icon-only]) .ui-icon { order:1; box-sizing:content-box; padding:8px; border-radius:50%; background:color-mix(in oklab,var(--p-on-accent) 16%,transparent); }
.ds .ds-button[data-look="cta"]:not([data-variant="primary"]):not([data-icon-only]) .ui-icon { background:var(--p-soft); }

.ds .ds-badge { display:inline-flex; align-items:center; width:fit-content; padding:4px 10px; border:1px solid var(--p-line); border-radius:99px; background:var(--p-soft); color:var(--p-ink); font-size:12px; line-height:1.5; font-weight:600; }
.ds .ds-badge[data-tone="success"] { background:var(--p-success-soft); border-color:var(--p-success-line); color:var(--p-success); }
.ds .ds-badge[data-tone="error"] { background:var(--p-error-soft); border-color:var(--p-error-line); color:var(--p-error); }
.ds .ds-badge[data-tone="warning"] { background:var(--p-warning-soft); border-color:var(--p-warning-line); color:var(--p-warning); }
/* looks: tone keeps the color, look changes the shape */
.ds .ds-badge[data-look="outline"] { background:transparent; border-color:currentColor; }
.ds .ds-badge[data-look="solid"] { background:var(--p-accent); border-color:var(--p-accent); color:var(--p-on-accent); }
.ds .ds-badge[data-look="solid"][data-tone="success"] { background:var(--p-success); border-color:var(--p-success); }
.ds .ds-badge[data-look="solid"][data-tone="error"] { background:var(--p-error); border-color:var(--p-error); }
.ds .ds-badge[data-look="solid"][data-tone="warning"] { background:var(--p-warning); border-color:var(--p-warning); }
.ds .ds-badge[data-look="dot"] { gap:6px; background:var(--p-bg); }
.ds .ds-badge[data-look="dot"]::before { content:''; width:8px; height:8px; border-radius:50%; background:currentColor; }
.ds .ds-badge[data-look="square"] { border-radius:6px; }
.ds .ds-badge[data-look="tag"] { padding-left:18px; border-color:transparent; border-radius:0 6px 6px 0; clip-path:polygon(10px 0,100% 0,100% 100%,10px 100%,0 50%); }
.ds .ds-badge[data-look="raised"] { background:var(--p-bg); border-color:transparent; box-shadow:var(--p-raised); }

.ds .ds-divider { border:0; border-top:1px solid var(--p-line); margin:0; width:100%; }
/* looks: shapes of the same rule, tokens only */
.ds .ds-divider[data-look="dashed"] { border-top:2px dashed var(--p-control-border); }
.ds .ds-divider[data-look="dotted"] { border:0; height:4px; background:radial-gradient(circle,var(--p-control-border) 1.5px,transparent 2px) 0 50%/10px 4px repeat-x; }
.ds .ds-divider[data-look="label"] { border:0; height:auto; overflow:visible; text-align:center; line-height:1.5; background:linear-gradient(var(--p-line),var(--p-line)) 0 50%/100% 1px no-repeat; }
.ds .ds-divider[data-look="label"]::after { content:attr(data-label); display:inline-block; padding:0 12px; background:var(--p-bg); color:var(--p-muted); font-size:var(--p-text-sm); }
.ds .ds-divider[data-look="inset"] { width:calc(100% - 56px); margin-left:auto; }
.ds .ds-divider[data-look="bar"] { width:48px; height:4px; border:0; border-radius:99px; background:var(--p-accent); margin-inline:auto; }
.ds .ds-divider[data-look="fade"] { border:0; height:1px; background:linear-gradient(90deg,transparent,var(--p-control-border),transparent); }
.ds .ds-divider[data-look="thick"] { border:0; border-block:1px solid var(--p-line); height:10px; background:var(--p-surface); }

.ds .ds-card { display:flex; flex-direction:column; height:100%; background:var(--p-surface); border:1px solid var(--p-line); border-radius:var(--p-radius); box-shadow:var(--p-raised); overflow:hidden; }
.ds .ds-card[data-selected="true"] { border-color:var(--p-success); background:var(--p-selected-surface); }
.ds .ds-card-body { flex:1; padding:var(--p-space-lg); }
.ds .ds-card h3 { font-size:20px; line-height:1.45; font-weight:650; letter-spacing:-.035em; margin-top:var(--p-space-md); }
.ds .ds-card p { font-size:14px; color:var(--p-muted); margin-top:var(--p-space-xs); }
.ds .ds-card-actions { display:flex; justify-content:flex-end; padding:var(--p-space-md) var(--p-space-lg); }
/* Looks: :where keeps each look as weak as the base rule, so a selected card still shows its selected state. */
.ds .ds-card:where([data-look="line"]) { box-shadow:none; }
.ds .ds-card:where([data-look="float"]) { border-color:transparent; background:var(--p-high); box-shadow:0 18px 36px -16px color-mix(in oklab, var(--p-accent) 38%, transparent); }
.ds .ds-card:where([data-look="fill"]) { border-color:transparent; background:var(--p-soft); box-shadow:none; }
.ds .ds-card:where([data-look="row"]) { display:grid; grid-template-columns:88px minmax(0,1fr); align-content:start; }
.ds .ds-card:where([data-look="row"]) .ds-card-media { height:auto; aspect-ratio:1; margin:var(--p-space-lg) 0 0 var(--p-space-lg); border-radius:16px; }
.ds .ds-card:where([data-look="row"]) .ds-card-body { padding-left:var(--p-space-md); }
.ds .ds-card:where([data-look="row"]) :is(.ds-divider,.ds-card-actions) { grid-column:1/-1; }
.ds .ds-card-media { height:96px; flex:none; background:radial-gradient(circle at 78% 34%, var(--p-high) 0 13px, transparent 14px), linear-gradient(160deg, transparent 58%, color-mix(in oklab, var(--p-success) 55%, var(--p-soft)) 58%), linear-gradient(135deg, var(--p-soft), color-mix(in oklab, var(--p-success) 30%, var(--p-soft))); }
.ds .ds-card:where([data-look="glass"]) { border-color:color-mix(in oklab, var(--p-high) 70%, transparent); background:var(--p-high); box-shadow:0 12px 30px -14px color-mix(in oklab, var(--p-accent) 35%, transparent); }
@supports(backdrop-filter:blur(16px)) { .ds .ds-card:where([data-look="glass"]) { background:color-mix(in oklab, var(--p-glass) 58%, transparent); backdrop-filter:blur(16px) saturate(1.4); } }
@media(prefers-reduced-transparency:reduce) { .ds .ds-card:where([data-look="glass"]) { background:var(--p-high); backdrop-filter:none; } }
.ds .ds-card:where([data-look="neumorph"]) { border-color:transparent; background:var(--p-surface); box-shadow:var(--p-shadow); }
.ds .ds-card:where([data-look="accent"]) { border-top:4px solid var(--p-accent); }

(function mountParts(root) {
  root.querySelectorAll('[data-indeterminate]').forEach(input => {
    if (!input.__pattoveInitialized) { input.indeterminate = true; input.__pattoveInitialized = true; }
  });
  if (root.__pattovePartsMounted) return;
  root.__pattovePartsMounted = true;
  function selectTab(tab) {
    const tabs = tab.closest('.ds-tabs');
    tabs.querySelectorAll('[role="tab"]').forEach(item => {
      const active = item === tab;
      item.setAttribute('aria-selected', String(active)); item.tabIndex = active ? 0 : -1;
      tabs.querySelector('#' + CSS.escape(item.getAttribute('aria-controls'))).hidden = !active;
    });
    tabs.dispatchEvent(new CustomEvent('pattove:tabchange', { bubbles: true, detail: { label: tab.textContent.trim(), panel: tab.getAttribute('aria-controls') } }));
  }
  function filter(form) {
    const module = form.closest('.ds-search-module');
    const query = form.elements.query.value.trim().toLocaleLowerCase();
    const status = form.elements.status.value;
    let count = 0;
    module.querySelectorAll('[data-result]').forEach(item => {
      const match = query.split(/\s+/).every(term => item.dataset.result.toLocaleLowerCase().includes(term)) && (status === 'all' || item.dataset.resultStatus === status);
      item.hidden = !match; if (match) count++;
    });
    module.querySelector('.ds-result-count').textContent = count + '개의 컬렉션';
    module.querySelector('.ds-empty').hidden = count > 0;
    module.querySelector('.ds-demo-note').textContent = '';
  }
  root.addEventListener('submit', event => {
    if (!event.target.matches('[data-part-search]')) return;
    event.preventDefault(); filter(event.target);
  });
  root.addEventListener('change', event => {
    // The status filter is a select, or a radio chip group in the chips look.
    if (event.target.matches('[data-part-search] [name="status"]')) filter(event.target.form);
  });
  root.addEventListener('click', event => {
    const tab = event.target.closest('.ds-tab');
    if (tab) selectTab(tab);
    const button = event.target.closest('[data-part-action]');
    if (!button || button.disabled) return;
    const action = button.dataset.partAction;
    if (['open-record', 'close-record', 'save-record'].includes(action)) {
      const module = button.closest('.ds-search-module');
      const detail = module.querySelector('.ds-record-detail');
      if (action === 'save-record') {
        button.setAttribute('aria-pressed', String(button.getAttribute('aria-pressed') !== 'true'));
        module.__recordOpener.dataset.saved = button.getAttribute('aria-pressed');
        module.__recordOpener.setAttribute('aria-label', module.querySelector('.ds-record-detail h3').textContent + (button.getAttribute('aria-pressed') === 'true' ? ', 보관됨, 상세 열기' : ', 상세 열기'));
        module.querySelector('.ds-demo-note').textContent = button.getAttribute('aria-pressed') === 'true' ? '이 화면에서 컬렉션에 보관했어요.' : '보관을 해제했어요.';
        const record = module.__recordOpener.closest('[data-result]');
        module.dispatchEvent(new CustomEvent('pattove:save', { bubbles: true, detail: {
          id: record.dataset.recordId,
          title: detail.querySelector('h3').textContent,
          description: detail.querySelector('p').textContent,
          tag: record.dataset.resultStatus,
          saved: button.getAttribute('aria-pressed') === 'true'
        } }));
        return;
      }
      const open = action === 'open-record';
      if (open) {
        module.__recordOpener = button;
        const card = button.closest('.ds-card');
        detail.querySelector('h3').textContent = card.querySelector('h3').textContent;
        detail.querySelector('p').textContent = card.querySelector('.ds-card-body > p').textContent;
        detail.querySelector('[data-part-action="save-record"]').setAttribute('aria-pressed', button.dataset.saved || 'false');
      }
      module.querySelectorAll(':scope > form, :scope > .ds-result-count, :scope > .ds-results').forEach(element => { element.hidden = open; });
      detail.hidden = !open;
      module.querySelector('.ds-demo-note').textContent = '';
      if (open) detail.focus(); else module.__recordOpener?.focus();
    } else if (action === 'notify') {
      button.closest('.ds-feedback-example').querySelector('[data-part-feedback]').hidden = false;
    } else if (action === 'nav') {
      const items = [...button.closest('nav').querySelectorAll(':scope > [data-part-action="nav"]')];
      items.forEach(item => item.setAttribute('aria-pressed', String(item === button)));
      button.dispatchEvent(new CustomEvent('pattove:navigate', { bubbles: true, detail: { index: items.indexOf(button), label: button.textContent.trim() } }));
    } else if (action === 'create') {
      button.dispatchEvent(new CustomEvent('pattove:create', { bubbles: true }));
    } else if (action === 'select-card') {
      const card = button.closest('.ds-card');
      const selected = card.dataset.selected !== 'true';
      card.dataset.selected = String(selected);
      button.setAttribute('aria-pressed', String(selected));
      button.lastChild.textContent = selected ? '선택됨' : '선택하기';
      card.dispatchEvent(new CustomEvent('pattove:select', { bubbles: true, detail: { selected, title: card.querySelector('h3').textContent } }));
    } else if (action === 'reset-search') {
      const form = button.closest('.ds-search-module').querySelector('form');
      form.reset(); filter(form); form.elements.query.focus();
    } else if (action === 'press') {
      button.dispatchEvent(new CustomEvent('pattove:action', { bubbles: true, detail: { label: button.getAttribute('aria-label') || button.textContent.trim() } }));
      const region = button.closest('.ds-search-module, .part-demo, .specimen') || root;
      const output = region.querySelector('.ds-demo-note');
      if (output) {
        const card = button.closest('.ds-card');
        output.textContent = card ? card.querySelector('h3').textContent + ' 선택됨' : (button.getAttribute('aria-label') || button.textContent.trim()) + ' 버튼을 눌렀어요.';
      }
    }
  });
  root.addEventListener('keydown', event => {
    const tab = event.target.closest('.ds-tab');
    if (!tab) return;
    const list = tab.closest('[role="tablist"]');
    // A vertical tab list moves with the up and down arrows, a horizontal one with left and right.
    const [back, forward] = list.getAttribute('aria-orientation') === 'vertical' ? ['ArrowUp', 'ArrowDown'] : ['ArrowLeft', 'ArrowRight'];
    if (![back, forward, 'Home', 'End'].includes(event.key)) return;
    event.preventDefault();
    const tabs = [...list.querySelectorAll('.ds-tab')];
    const current = tabs.indexOf(tab);
    const next = event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : (current + (event.key === forward ? 1 : -1) + tabs.length) % tabs.length;
    selectTab(tabs[next]); tabs[next].focus();
  });
})(document);

